import os
import re
import json
import hashlib
import hmac
import time
import socket
from urllib.parse import urlparse, urljoin
from http.server import HTTPServer, BaseHTTPRequestHandler
from urllib.request import urlopen, Request
from urllib.error import URLError
import ssl

SECRET_KEY = os.environ.get('WEBHOOK_SECRET', os.urandom(32))
ALLOWED_SCHEMES = ('https',)
BLOCKED_RANGES = [
    ('10.0.0.0', '10.255.255.255'),
    ('172.16.0.0', '172.31.255.255'),
    ('192.168.0.0', '192.168.255.255'),
    ('127.0.0.0', '127.255.255.255'),
    ('169.254.0.0', '169.254.255.255'),
]

def ip_to_int(ip):
    parts = ip.split('.')
    return (int(parts[0]) << 24) + (int(parts[1]) << 16) + (int(parts[2]) << 8) + int(parts[3])

def is_private_ip(ip_str):
    try:
        ip_int = ip_to_int(ip_str)
        for start, end in BLOCKED_RANGES:
            if ip_to_int(start) <= ip_int <= ip_to_int(end):
                return True
        return False
    except (ValueError, IndexError):
        return True

def resolve_and_check(hostname):
    """Resolve hostname and verify it doesn't point to internal infrastructure."""
    try:
        addr_info = socket.getaddrinfo(hostname, None, socket.AF_INET)
        for family, socktype, proto, canonname, sockaddr in addr_info:
            ip = sockaddr[0]
            if is_private_ip(ip):
                return False, ip
        return True, addr_info[0][4][0]
    except socket.gaierror:
        return False, None

def validate_webhook_url(url):
    """Validate that a webhook URL is safe to call.

    Uses Python's urlparse for robust URL parsing, then validates
    the scheme, hostname, and resolved IP address.
    """
    parsed = urlparse(url)

    # Verify scheme
    if parsed.scheme not in ALLOWED_SCHEMES:
        return False, "Invalid scheme"

    # Verify hostname exists
    hostname = parsed.hostname
    if not hostname:
        return False, "No hostname"

    # Block IP-based URLs to prevent direct IP access
    try:
        socket.inet_aton(hostname)
        return False, "Direct IP not allowed"
    except socket.error:
        pass

    # Verify hostname has valid TLD
    if '.' not in hostname:
        return False, "Invalid hostname"

    # DNS resolution check
    is_safe, resolved_ip = resolve_and_check(hostname)
    if not is_safe:
        return False, f"Hostname resolves to blocked IP: {resolved_ip}"

    return True, resolved_ip

def verify_request_signature(body, signature, secret):
    """Verify webhook registration request signature."""
    if not signature:
        return False
    expected = hmac.new(secret if isinstance(secret, bytes) else secret.encode(),
                       body, hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, signature)

def fetch_webhook_url(url, payload):
    """Make the outbound webhook request."""
    is_valid, info = validate_webhook_url(url)
    if not is_valid:
        return {'error': info, 'status': 'blocked'}

    try:
        ctx = ssl.create_default_context()
        req = Request(url, data=json.dumps(payload).encode(),
                     headers={'Content-Type': 'application/json'})
        resp = urlopen(req, timeout=5, context=ctx)
        return {'status': 'delivered', 'code': resp.getcode()}
    except URLError as e:
        return {'status': 'failed', 'error': str(e)}

class WebhookHandler(BaseHTTPRequestHandler):
    webhooks = {}

    def do_POST(self):
        content_length = int(self.headers.get('Content-Length', 0))
        body = self.rfile.read(content_length)

        if self.path == '/webhooks/register':
            self._handle_register(body)
        elif self.path == '/webhooks/trigger':
            self._handle_trigger(body)
        else:
            self._respond(404, {'error': 'not found'})

    def _handle_register(self, body):
        sig = self.headers.get('X-Signature')
        if not verify_request_signature(body, sig, SECRET_KEY):
            self._respond(401, {'error': 'invalid signature'})
            return

        try:
            data = json.loads(body)
        except json.JSONDecodeError:
            self._respond(400, {'error': 'invalid json'})
            return

        url = data.get('url', '')
        hook_id = data.get('id', '')

        if not url or not hook_id:
            self._respond(400, {'error': 'missing fields'})
            return

        # Pre-validate the URL at registration time
        is_valid, info = validate_webhook_url(url)
        if not is_valid:
            self._respond(400, {'error': f'invalid url: {info}'})
            return

        self.webhooks[hook_id] = {'url': url, 'registered_at': time.time()}
        self._respond(201, {'status': 'registered', 'id': hook_id})

    def _handle_trigger(self, body):
        try:
            data = json.loads(body)
        except json.JSONDecodeError:
            self._respond(400, {'error': 'invalid json'})
            return

        hook_id = data.get('id', '')
        payload = data.get('payload', {})

        if hook_id not in self.webhooks:
            self._respond(404, {'error': 'webhook not found'})
            return

        webhook = self.webhooks[hook_id]
        result = fetch_webhook_url(webhook['url'], payload)
        self._respond(200, result)

    def _respond(self, code, data):
        self.send_response(code)
        self.send_header('Content-Type', 'application/json')
        self.end_headers()
        self.wfile.write(json.dumps(data).encode())

if __name__ == '__main__':
    server = HTTPServer(('0.0.0.0', 8080), WebhookHandler)
    server.serve_forever()
